{
  "name": "Opentrons GEN-1/GEN-2 PCR热循环仪",
  "name_en": "Opentrons GEN-1/GEN-2 Thermocycler",
  "manufacturer": "Opentrons",
  "description": "一款用于PCR扩增的实验室热循环仪，配有可精确控温的样品块和加热上盖，可对PCR板中的样品执行变性、退火和延伸等温度循环步骤，适用于自动化分子生物学实验流程。",
  "description_en": "A laboratory thermocycler for PCR amplification, featuring a precisely controlled sample block and a heated lid. It performs denaturation, annealing, and extension temperature cycles on PCR plates and is suited for automated molecular biology workflows.",
  "tag_hints": [
    "PCR thermocycling",
    "heated lid",
    "temperature-controlled block",
    "PCR plate handling",
    "automated molecular biology",
    "Opentrons automation"
  ],
  "actions": [
    {
      "action_name": "auto-close_lid",
      "description": "关闭热循环仪上盖",
      "description_en": "Close the thermocycler lid."
    },
    {
      "action_name": "auto-deactivate_block",
      "description": "关闭样品块加热",
      "description_en": "Turn off block heating."
    },
    {
      "action_name": "auto-deactivate_lid",
      "description": "关闭上盖加热",
      "description_en": "Turn off lid heating."
    },
    {
      "action_name": "auto-jog_lid",
      "description": "将上盖移动到指定角度位置",
      "description_en": "Move the lid to a specified angle position."
    },
    {
      "action_name": "auto-lift_plate",
      "description": "抬起PCR板，便于机械臂拾取",
      "description_en": "Lift the plate to help a robot arm pick it up."
    },
    {
      "action_name": "auto-open_lid",
      "description": "打开热循环仪上盖",
      "description_en": "Open the thermocycler lid."
    },
    {
      "action_name": "auto-run_protocol",
      "description": "执行PCR温度循环程序",
      "description_en": "Run a thermocycling protocol."
    },
    {
      "action_name": "auto-set_block_temperature",
      "description": "设置样品块温度",
      "description_en": "Set the block temperature."
    },
    {
      "action_name": "auto-set_lid_temperature",
      "description": "设置上盖温度",
      "description_en": "Set the lid temperature."
    },
    {
      "action_name": "auto-set_ramp_rate",
      "description": "设置升降温速率",
      "description_en": "Set the temperature ramp rate."
    },
    {
      "action_name": "auto-setup",
      "description": "连接并初始化热循环仪",
      "description_en": "Connect to and initialize the thermocycler."
    },
    {
      "action_name": "auto-stop",
      "description": "停止当前运行",
      "description_en": "Stop the current run."
    },
    {
      "action_name": "auto-get_device_info",
      "description": "获取设备信息",
      "description_en": "Get device information."
    },
    {
      "action_name": "auto-get_block_current_temperature",
      "description": "获取样品块当前温度",
      "description_en": "Get the current block temperature."
    },
    {
      "action_name": "auto-get_block_target_temperature",
      "description": "获取样品块目标温度",
      "description_en": "Get the target block temperature."
    },
    {
      "action_name": "auto-get_lid_current_temperature",
      "description": "获取上盖当前温度",
      "description_en": "Get the current lid temperature."
    },
    {
      "action_name": "auto-get_lid_target_temperature",
      "description": "获取上盖目标温度",
      "description_en": "Get the target lid temperature."
    },
    {
      "action_name": "auto-get_lid_open",
      "description": "获取上盖是否打开",
      "description_en": "Get whether the lid is open."
    },
    {
      "action_name": "auto-get_lid_status",
      "description": "获取上盖状态",
      "description_en": "Get lid status."
    },
    {
      "action_name": "auto-get_block_status",
      "description": "获取样品块状态",
      "description_en": "Get block status."
    },
    {
      "action_name": "auto-get_hold_time",
      "description": "获取当前保温时间",
      "description_en": "Get the current hold time."
    },
    {
      "action_name": "auto-get_current_cycle_index",
      "description": "获取当前循环序号",
      "description_en": "Get the current cycle index."
    },
    {
      "action_name": "auto-get_total_cycle_count",
      "description": "获取总循环次数",
      "description_en": "Get the total cycle count."
    },
    {
      "action_name": "auto-get_current_step_index",
      "description": "获取当前步骤序号",
      "description_en": "Get the current step index."
    },
    {
      "action_name": "auto-get_total_step_count",
      "description": "获取总步骤数",
      "description_en": "Get the total step count."
    }
  ]
}

